5	use Spatie\Image\Image;
6	use Throwable;
7	
8	class ImageProcessor
9	{
10	    public const MAX_WIDTH = 2560;
11	    public const WEBP_QUALITY = 82;
12	    public const CONVERTIBLE = ['jpg', 'jpeg', 'png', 'gif'];
13	
14	    /**
15	     * 업로드된 원본 이미지 옆에 .webp sibling 을 생성한다.
16	     * 원본은 그대로 둔다. 실패해도 예외를 삼켜서 업로드 플로우를 깨뜨리지 않는다.
17	     */
18	    public static function makeWebpSibling(string $absolutePath): bool
19	    {
20	        if (!is_file($absolutePath)) {
21	            return false;
22	        }
23	
24	        $ext = strtolower(pathinfo($absolutePath, PATHINFO_EXTENSION));
25	        if (!in_array($ext, self::CONVERTIBLE, true)) {
26	            return false;
27	        }
28	
29	        $webpPath = preg_replace('/\.[^.]+$/', '.webp', $absolutePath);
30	
31	        try {
32	            $image = Image::load($absolutePath);
33	
34	            $size = @getimagesize($absolutePath);
35	            if (is_array($size) && isset($size[0]) && $size[0] > self::MAX_WIDTH) {
36	                $image->width(self::MAX_WIDTH);
37	            }
38	
39	            $image->format('webp')
40	                ->quality(self::WEBP_QUALITY)
41	                ->save($webpPath);
42	
43	            return is_file($webpPath);
44	        } catch (Throwable $e) {
45	            error_log('[ImageProcessor] webp sibling failed for ' . $absolutePath . ': ' . $e->getMessage());
46	            return false;
47	        }
48	    }
49	
50	    /**
51	     * 주어진 이미지 경로의 .webp sibling 을 삭제한다. 원본은 건드리지 않는다.
52	     * imageDelete() 에서 호출되어 삭제 시 동반 정리를 담당.
53	     */
54	    public static function deleteWebpSibling(string $absolutePath): bool
55	    {
56	        $ext = strtolower(pathinfo($absolutePath, PATHINFO_EXTENSION));
57	        if (!in_array($ext, self::CONVERTIBLE, true)) {
58	            return false;
59	        }
60	
61	        $webpPath = preg_replace('/\.[^.]+$/', '.webp', $absolutePath);
62	        if (is_file($webpPath)) {
63	            return @unlink($webpPath);
64	        }
65	
66	        return false;
67	    }
68	}
