284	function print_pagelist($page, $list_amount, $page_count, $param, $page_type = "")
285	{
286	    global $code, $catcode, $orderby, $skin_dir, $ptype, $NO_ADMIN_BASE;
287	    $skin_dir = $skin_dir ?: (($NO_ADMIN_BASE ?? '') . "/manage");
288	    $param = $param ? "&$param" : "";
289	
290	    $spage = floor(($page - 1) / $list_amount) * $list_amount + 1;
291	    $epage = min($spage + $list_amount - 1, $page_count);
292	    $ppage = max($spage - $list_amount, 1);
293	    $npage = min($epage + 1, $page_count);
294	    $page_name = $page_type === "C" ? "cpage" : "page";
295	
296	    if ($epage > 0) {
297	        echo "<div class='pagination'>";
298	        echo "<a href='?ptype=$ptype&$page_name=1$param'>◀◀</a>";
299	        echo "<a href='?ptype=$ptype&$page_name=$ppage$param'>◀</a>";
300	        for ($i = $spage; $i <= $epage; $i++) {
301	            echo $i === $page ? "<strong>$i</strong>" : "<a href='?ptype=$ptype&$page_name=$i$param'>$i</a>";
302	        }
303	        echo "<a href='?ptype=$ptype&$page_name=$npage$param'>▶</a>";
