323	if (!function_exists('safe_url')) {
324	    function safe_url(string $url, array $allowedSchemes = ['http', 'https'], bool $returnEmpty = false): ?string
325	    {
326	        $url = trim($url);
327	        if ($url === '') {
328	            return $returnEmpty ? '' : null;
329	        }
330	
331	        $scheme = strtolower((string) (parse_url($url, PHP_URL_SCHEME) ?? ''));
332	        if (!in_array($scheme, $allowedSchemes, true)) {
333	            return $returnEmpty ? '' : null;
334	        }
335	
336	        return filter_var($url, FILTER_VALIDATE_URL) !== false ? $url : ($returnEmpty ? '' : null);
337	    }
338	}
