235	/**
236	 * 현재 경로에서 언어 prefix를 변경한 URL 반환
237	 * 
238	 * @param string $locale 변경할 언어 코드 (ko, en)
239	 * @return string 언어 prefix가 변경된 URL
240	 */
241	if (!function_exists('locale_url')) {
242	    function locale_url(string $locale): string
243	    {
244	        // 유효한 언어 코드인지 확인
245	        if (!in_array($locale, locales(), true)) {
246	            $locale = DEFAULT_LOCALE;
247	        }
248	
249	        // 현재 경로 가져오기
250	        $currentPath = $_SERVER['REQUEST_URI'] ?? '/';
251	        
252	        // 쿼리스트링 분리
253	        $queryString = '';
254	        $pathOnly = $currentPath;
255	        if (($pos = strpos($currentPath, '?')) !== false) {
256	            $pathOnly = substr($currentPath, 0, $pos);
257	            $queryString = substr($currentPath, $pos);
258	        }
259	
260	        // 경로에서 언어 prefix 제거
261	        $segments = array_values(array_filter(explode('/', trim($pathOnly, '/')), 'strlen'));
262	        $firstSegment = $segments[0] ?? null;
263	        
264	        // 첫 번째 세그먼트가 언어 코드이면 제거
265	        if ($firstSegment !== null && in_array($firstSegment, locales(), true)) {
266	            array_shift($segments);
267	        }
268	
269	        // 새로운 경로 구성
270	        if (empty($segments)) {
271	            // 루트 경로인 경우
272	            $newPath = '/' . $locale;
273	        } else {
274	            // 하위 경로가 있는 경우
275	            $newPath = '/' . $locale . '/' . implode('/', $segments);
276	        }
277	
278	        // 쿼리스트링 추가
279	        return $newPath . $queryString;
280	    }
281	}

